const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to the annual green valley nature reserve orientation tour today.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.533333333333333},{"speaker":"A","text":"Before we begin our morning walk let me explain some important visitor arrangements.","position":2,"audioStartSeconds":5.733333333333333,"audioEndSeconds":11.003958333333333},{"speaker":"A","text":"Our main information centre opens every morning at nine o clock sharp.","position":3,"audioStartSeconds":11.203958333333333,"audioEndSeconds":15.843916666666667},{"speaker":"A","text":"You can collect your trail maps directly from the wooden reception desk inside.","position":4,"audioStartSeconds":16.043916666666668,"audioEndSeconds":20.992375},{"speaker":"A","text":"Please remember that all adult visitors must pay an entrance fee of six pounds.","position":5,"audioStartSeconds":21.192375,"audioEndSeconds":26.449333333333332},{"speaker":"A","text":"Children under twelve years old can enter the protected reserve completely free.","position":6,"audioStartSeconds":26.649333333333335,"audioEndSeconds":31.624333333333333},{"speaker":"A","text":"After you finish exploring the lower forest path please head toward the lake.","position":7,"audioStartSeconds":31.824333333333332,"audioEndSeconds":36.618125},{"speaker":"A","text":"We will gather together near the large stone bridge for our picnic lunch.","position":8,"audioStartSeconds":36.818125,"audioEndSeconds":41.173791666666666},{"speaker":"A","text":"If it starts raining heavily we will move inside the historic wooden boathouse.","position":9,"audioStartSeconds":41.37379166666667,"audioEndSeconds":46.425375},{"speaker":"A","text":"Everyone should bring waterproof jackets because mountain weather changes very quickly here.","position":10,"audioStartSeconds":46.625375,"audioEndSeconds":51.98616666666667},{"speaker":"A","text":"Photography is permitted everywhere except inside the bird nesting protection zone near the hills.","position":11,"audioStartSeconds":52.186166666666665,"audioEndSeconds":58.29441666666666},{"speaker":"A","text":"Finally do not forget to sign the visitor register before leaving this afternoon.","position":12,"audioStartSeconds":58.494416666666666,"audioEndSeconds":63.570083333333336}],"questions":[{"prompt":"Opening time: ______","answer":"nine o clock","evidenceSentence":3,"evidence":"nine o clock","explanation":"Hướng dẫn viên thông báo trung tâm thông tin mở cửa lúc chín giờ."},{"prompt":"Map collection point: ______","answer":"wooden reception desk","evidenceSentence":4,"evidence":"wooden reception desk","explanation":"Du khách có thể lấy bản đồ tại bàn tiếp tân bằng gỗ."},{"prompt":"Adult entrance fee: ______ pounds","answer":"six","evidenceSentence":5,"evidence":"six pounds","explanation":"Phí vào cổng cho người lớn là sáu bảng."},{"prompt":"Lunch meeting point: ______","answer":"stone bridge","evidenceSentence":8,"evidence":"stone bridge","explanation":"Mọi người sẽ tập trung ăn trưa gần cây cầu đá lớn."},{"prompt":"Rain shelter location: ______","answer":"boathouse","evidenceSentence":9,"evidence":"boathouse","explanation":"Nếu trời mưa to, đoàn sẽ di chuyển vào bên trong nhà thuyền lịch sử."},{"prompt":"Prohibited activity area: ______","answer":"bird nesting","evidenceSentence":11,"evidence":"bird nesting","explanation":"Việc chụp ảnh bị cấm ở khu vực bảo vệ tổ chim."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
